220:  private static void applyDdl(DataSource source) throws SQLException, IOException {
221:    String ddl;
222:    try (InputStream stream =
223:        T01PublicAcceptanceIT.class.getResourceAsStream("/ddl/mysql-v1-baseline.sql")) {
224:      if (stream == null) {
225:        throw new IllegalStateException("missing frozen DDL resource");
226:      }
227:      ddl = new String(stream.readAllBytes(), StandardCharsets.UTF_8);
228:    }
229:    String withoutComments = ddl.replaceAll("(?m)^\\s*--.*$", "");
230:    try (Connection connection = source.getConnection();
231:        Statement statement = connection.createStatement()) {
232:      for (String sql : withoutComments.split(";")) {
233:        if (!sql.isBlank()) {
234:          statement.execute(sql);
235:        }
236:      }
237:    }
238:  }
