240:  private static final class MutableContextAccessor implements ExecutionContextAccessor {
241:    private ExecutionContext current;
242:
243:    void set(ExecutionContext context) {
244:      current = context;
245:    }
246:
247:    @Override
248:    public Optional<ExecutionContext> current() {
249:      return Optional.ofNullable(current);
250:    }
251:  }
