253:  private static final class MutableClock extends Clock {
254:    private Instant instant;
255:
256:    MutableClock(Instant instant) {
257:      this.instant = instant;
258:    }
259:
260:    void set(Instant instant) {
261:      this.instant = instant;
262:    }
263:
264:    @Override
265:    public ZoneId getZone() {
266:      return ZoneId.of("UTC");
267:    }
268:
269:    @Override
270:    public Clock withZone(ZoneId zone) {
271:      return this;
272:    }
273:
274:    @Override
275:    public Instant instant() {
276:      return instant;
277:    }
278:  }
279:}

