25:    assertThrows(IllegalArgumentException.class, () -> new StoreId(0));
26:  }
27:
28:  @Test
29:  void executionContextScopeRestoresAfterSuccessAndFailure() {
30:    ScopedExecutionContext scope = new ScopedExecutionContext();
31:    ExecutionContext outer = context("outer");
32:    ExecutionContext inner = context("inner");
33:
34:    scope.run(
35:        outer,
36:        () -> {
37:          assertEquals(outer, scope.current().orElseThrow());
38:          assertThrows(
39:              IllegalStateException.class,
40:              () -> scope.run(inner, () -> { throw new IllegalStateException("boom"); }));
41:          assertEquals(outer, scope.current().orElseThrow());
42:        });
43:    assertEquals(true, scope.current().isEmpty());
44:  }
